+ LIMIT 1`,
+			values: [keys],
+		});
+		const map = {};
+		res.rows.forEach((d) => {
+			map[d._key] = d.data;
+		});
+		return keys.map(k => (map.hasOwnProperty(k) ? map[k] : null));
+	};
