+        className="mx_DeviceDetailHeading_renameForm"
+        onSubmit={onSubmit}
+        method="post"
+    >
+        <p
+            id={headingId}
+            className="mx_DeviceDetailHeading_renameFormHeading"
+        >
+            { _t('Rename session') }
+        </p>
