+              response:
+                type: object
+                properties: {}
+put:
+  tags:
+    - group
+  summary: accept group invitation
+  description: |
+    This operation accepts an invitation to join a group.
+    > **N.B.** This route can only be called by the invited user.
+  parameters:
+    - in: path
+      name: slug
+      schema:
+        type: string
+      required: true
