+}
+
+func (w *wal2jsonMessage) Events() ([]backend.Event, error) {
+	switch w.Action {
+	case "B", "C", "M":
+		return nil, nil
+	default:
+		return nil, trace.BadParameter("unexpected action %q", w.Action)
+
+	case "T":
