 }
+
+type InPlaylist map[string]interface{}
+
+func (ipl InPlaylist) ToSql() (sql string, args []interface{}, err error) {
+	return inList(ipl, false)
+}
+
+func (ipl InPlaylist) MarshalJSON() ([]byte, error) {
