+            <span className={clsx('label-stack-item-inner text-ellipsis cursor-pointer', selected && '')}>
+                <span className="label-stack-item-text color-primary">{text}</span>
+            </span>
+        </Tooltip>
+    );
+};
+
+export default ProtonBadge;
