+			c := &dynamodb.UpdateItemInput{
+				TableName:                 aws.String(l.Tablename),
+				Key:                       key,
+				ExpressionAttributeValues: attributeMap,
+				UpdateExpression:          aws.String("SET CreatedAtDate = :date"),
+			}
